    public void valueOf_EmptyTagName_ReturnsUnknownTag() {
        // [valueOf][EmptyTagName]Test
        String tagName = "";
        when(settings.getNames()).thenReturn(new HashMap<>());
        Tag tag = Tag.valueOf(tagName);
        assertTrue(Tag.isKnownTag(tagName));
